export const SITE_V005_HTML="<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#080b10\">\n<meta name=\"description\" content=\"ANEVUM Sites is an experimental digital studio in St. Cloud, Florida. Explore live 3D experiences, playable browser games, stateful interfaces, and installable web applications.\">\n<meta name=\"robots\" content=\"index,follow\">\n<meta property=\"og:title\" content=\"ANEVUM SITES — The internet is our material\">\n<meta property=\"og:description\" content=\"Worlds. Games. Applications. Experiences. Built beyond the template.\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:url\" content=\"https://web.anevum.com/\">\n<link rel=\"canonical\" href=\"https://web.anevum.com/\">\n<link rel=\"icon\" href=\"/assets/sites-v005-icon.svg\" type=\"image/svg+xml\">\n\n<link rel=\"manifest\" href=\"/site.webmanifest\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"/assets/sites-v005.css\">\n<title>ANEVUM SITES — The Internet Is Our Material</title>\n</head>\n<body class=\"v5\">\n<a class=\"skip\" href=\"#main\">Skip to content</a>\n<div class=\"ambient\" aria-hidden=\"true\"></div>\n<div class=\"utility-bar\"><div class=\"frame utility-inner\"><span><span class=\"status-dot\"></span> THE CONTINUANCE INSTITUTE / INDEPENDENT DIGITAL ATELIER</span><span class=\"utility-right\">ST. CLOUD, FL / WORKING WORLDWIDE <span class=\"divider-mono\">//</span> EST. 2026</span></div></div>\n<header class=\"main-header\">\n<div class=\"frame nav-frame\">\n<a class=\"brand\" href=\"/\" aria-label=\"ANEVUM Sites home\"><span class=\"brand-emblem\" aria-hidden=\"true\"><span></span></span><span class=\"brand-word\">ANEVUM<span class=\"brand-slash\"> / </span><span class=\"brand-sites\">SITES</span></span></a>\n<nav class=\"desktop-nav\" aria-label=\"Main navigation\"><a href=\"#experience\">The Lab</a><a href=\"#capabilities\">Capabilities</a><a href=\"#approach\">How We Build</a><a href=\"#pricing\">Start Small</a></nav>\n<a class=\"nav-cta\" href=\"#contact\">INITIATE A PROJECT <span aria-hidden=\"true\">↗</span></a>\n<details class=\"mobile-menu\"><summary aria-label=\"Open navigation\"><span></span><span></span><span></span></summary><nav aria-label=\"Mobile navigation\"><a href=\"#experience\">Explore The Lab</a><a href=\"#capabilities\">Capabilities</a><a href=\"#approach\">Process</a><a href=\"#pricing\">Starting Prices</a><a href=\"#contact\">Initiate a Project ↗</a></nav></details>\n</div>\n</header>\n<main id=\"main\">\n<section class=\"hero frame\" aria-labelledby=\"hero-title\">\n<div class=\"hero-copy\">\n<div class=\"eyebrow\"><span class=\"eyebrow-line\"></span> SOFTWARE / ART / EXPERIMENT  <span class=\"index\">[ 001 — ∞ ]</span></div>\n<h1 id=\"hero-title\">THE INTERNET<br>IS OUR <span class=\"hero-highlight\">MATERIAL<span class=\"hero-period\">.</span></span></h1>\n<p class=\"hero-lead\">We do not stop at a nice-looking webpage. We design and engineer <strong>interactive worlds, browser games, custom applications, 3D experiences, and software you can install.</strong> The idea sets the direction. We build what works.</p>\n<div class=\"hero-actions\"><a class=\"primary-button\" href=\"#experience\">ENTER THE EXPERIENCE LAB <span aria-hidden=\"true\">↘</span></a><a class=\"text-button\" href=\"#contact\">HAVE AN IDEA? <span aria-hidden=\"true\">↗</span></a></div>\n<div class=\"hero-labline\"><span class=\"led\"></span> THE 3D OBJECT TO THE RIGHT IS LIVE. DRAG IT.</div>\n</div>\n<div class=\"hero-visual\" aria-label=\"Interactive real-time three-dimensional sculpture\">\n<div class=\"hero-visual-top\"><span>LIVE ARTIFACT <b>ANV—001</b></span><span class=\"live-badge\"><i></i> RENDERING</span></div>\n<div id=\"hero-react-root\" class=\"hero-react-root\"><div class=\"art-fallback\"><span class=\"fallback-core\"></span><span class=\"fallback-ring\"></span><span class=\"fallback-ring alt\"></span></div></div>\n<div class=\"hero-hud-left\">RENDER / REALTIME<br>MODE / INTERACTIVE<br>INPUT / TOUCH + POINTER</div>\n<div class=\"hero-visual-bottom\"><span>◉ &nbsp; DRAG TO ROTATE</span><span>REAL WEBGL · NOT A VIDEO</span></div>\n<div class=\"hero-cross one\" aria-hidden=\"true\">+</div><div class=\"hero-cross two\" aria-hidden=\"true\">+</div>\n</div>\n<div class=\"hero-footer\"><span>BUILT TO FEEL IMPOSSIBLE. ENGINEERED TO ACTUALLY WORK.</span><span>SCROLL TO RUN THE EXPERIMENTS <span aria-hidden=\"true\">↓</span></span></div>\n</section>\n<div class=\"signal-strip\" aria-label=\"Technology and capability summary\"><div class=\"signal-track\"><span>IMMERSIVE 3D</span><b>✳</b><span>STATEFUL INTERFACES</span><b>✳</b><span>BROWSER GAMES</span><b>✳</b><span>INSTALLABLE PWAs</span><b>✳</b><span>CUSTOM APPLICATIONS</span><b>✳</b><span>REAL INTEGRATIONS</span><b>✳</b><span>IMMERSIVE 3D</span><b>✳</b><span>REACT INTERFACES</span><b>✳</b></div></div>\n<section class=\"experience-section section-frame\" id=\"experience\" aria-labelledby=\"lab-title\">\n<div class=\"frame\">\n<div class=\"section-header\"><div><span class=\"eyebrow\"><span class=\"eyebrow-line\"></span> 01 / THE EXPERIENCE LAB</span><h2 id=\"lab-title\">DON'T TAKE OUR WORD FOR IT.<br><em>TOUCH THE WORK.</em></h2></div><div class=\"section-header-aside\"><span class=\"monotag\">[ INTERACTIVE PROTOTYPES ]</span><p>Four working experiments. Rotate an object. Play a game. Configure software. Install an app. Everything here responds to you; these are demos, not invented customer projects.</p></div></div>\n<div id=\"experience-react-root\" class=\"experience-react-root\"><div class=\"lab-loading\"><span class=\"loader-orbit\"></span><span>INITIALIZING EXPERIMENTS...</span><small>ENABLE JAVASCRIPT TO USE THE INTERACTIVE LAB.</small></div></div>\n<div class=\"lab-footer-note\"><span>ENGINEERED ON THE OPEN WEB</span><span>DEMOS RUN LOCALLY IN YOUR BROWSER · NO ACCOUNT REQUIRED</span></div>\n</div>\n</section>\n<section class=\"capabilities-section section-frame\" id=\"capabilities\" aria-labelledby=\"cap-title\">\n<div class=\"frame\">\n<div class=\"section-header capabilities-head\"><div><span class=\"eyebrow\"><span class=\"eyebrow-line\"></span> 02 / WHAT WE CAN ENGINEER</span><h2 id=\"cap-title\">NOT ONE KIND OF<br><em>INTERNET THING.</em></h2></div><p class=\"section-intro\">Design, development, interfaces, animation, data, interactivity, and infrastructure—assembled around the problem rather than a template.</p></div>\n<div class=\"capability-grid\">\n<article class=\"capability-card cap-large\"><div class=\"cap-top\"><span class=\"cap-number\">01 — IMMERSIVE</span><span class=\"cap-arrow\">↗</span></div><div class=\"cap-illustration\" aria-hidden=\"true\"><div class=\"cap-geosphere\"><i></i><i></i><i></i></div><div class=\"cap-orbit outer\"></div><div class=\"cap-orbit inner\"></div></div><div class=\"cap-bottom\"><h3>3D & immersive worlds</h3><p>Real-time WebGL, procedural graphics, interactive models, motion systems, and spatial presentations.</p><a href=\"#experience\">TRY THE 3D EXPERIMENT ↗</a></div></article>\n<article class=\"capability-card cap-purple\"><div class=\"cap-top\"><span class=\"cap-number\">02 — PLAYABLE</span><span class=\"cap-arrow\">↗</span></div><div class=\"cap-illustration arcade\" aria-hidden=\"true\"><span class=\"arcade-player\">▲</span><span class=\"arcade-asteroid a\">◆</span><span class=\"arcade-asteroid b\">◇</span><span class=\"arcade-asteroid c\">✦</span><span class=\"arcade-line\"></span></div><div class=\"cap-bottom\"><h3>Games & interactive stories</h3><p>Playable browser experiences, touch controls, progression, physics concepts, and creative tools.</p><a href=\"#experience\">PLAY THE PROTOTYPE ↗</a></div></article>\n<article class=\"capability-card cap-blue\"><div class=\"cap-top\"><span class=\"cap-number\">03 — ENGINEERED</span><span class=\"cap-arrow\">↗</span></div><div class=\"cap-illustration ui-scene\" aria-hidden=\"true\"><div class=\"ui-preview\"><div class=\"ui-top\"><i></i><i></i><i></i></div><div class=\"ui-cards\"><span></span><span></span><span></span></div><div class=\"ui-graph\"><b></b><b></b><b></b><b></b><b></b></div></div></div><div class=\"cap-bottom\"><h3>Custom apps & real systems</h3><p>Dashboards, member spaces, software utilities, booking workflows, databases, and secure integrations.</p><a href=\"#experience\">CONFIGURE AN APP ↗</a></div></article>\n<article class=\"capability-card cap-orange\"><div class=\"cap-top\"><span class=\"cap-number\">04 — EVERYWHERE</span><span class=\"cap-arrow\">↗</span></div><div class=\"cap-illustration device-scene\" aria-hidden=\"true\"><div class=\"device-phone\"><div class=\"device-camera\"></div><div class=\"device-content\"><span>ANEVUM</span><b>YOUR WORLD.<br>IN YOUR POCKET.</b><i></i><i></i><i></i></div></div></div><div class=\"cap-bottom\"><h3>Installable PWAs</h3><p>Home Screen installation, offline-capable interfaces, notifications where supported, and mobile-first systems.</p><a href=\"#experience\">EXPLORE INSTALLATION ↗</a></div></article>\n<article class=\"capability-card cap-dark\"><div class=\"cap-top\"><span class=\"cap-number\">05 — CONNECTED</span><span class=\"cap-arrow\">↗</span></div><div class=\"cap-illustration integration-scene\" aria-hidden=\"true\"><span>API</span><i class=\"connect a\"></i><i class=\"connect b\"></i><i class=\"connect c\"></i><b class=\"node a\">↗</b><b class=\"node b\">⚙</b><b class=\"node c\">◈</b></div><div class=\"cap-bottom\"><h3>AI, automation & integrations</h3><p>Purpose-built connections to models, payments, data, publishing systems, and third-party tools when the project needs them.</p><a href=\"#contact\">DISCUSS YOUR WORKFLOW ↗</a></div></article>\n</div>\n<p class=\"scope-note\">Each system is scoped and validated individually. This page demonstrates selected real interactions, not a claim that every possible integration is already configured.</p>\n</div>\n</section>\n<section class=\"approach-section section-frame\" id=\"approach\" aria-labelledby=\"approach-title\">\n<div class=\"frame approach-layout\"><div class=\"approach-copy\"><span class=\"eyebrow\"><span class=\"eyebrow-line\"></span> 03 / METHOD OVER MAGIC</span><h2 id=\"approach-title\">MAD SCIENTIST<br><em>INSTINCT.</em><br>ENGINEER'S<br>DISCIPLINE.</h2><p>Wild ideas deserve serious execution. We find the smallest version that proves the experience, make it work on real devices, then expand only where the result earns it.</p><a class=\"text-button approach-link\" href=\"#contact\">LET'S DESIGN SOMETHING UNUSUAL ↗</a></div>\n<div class=\"approach-steps\">\n<div class=\"approach-step\"><span>01</span><div><h3>Define the impossible part.</h3><p>Tell us the problem and the feeling the finished experience should create.</p></div><b>↗</b></div>\n<div class=\"approach-step\"><span>02</span><div><h3>Build a working experiment.</h3><p>We validate the hard interaction before covering it in pretty mockups.</p></div><b>↗</b></div>\n<div class=\"approach-step\"><span>03</span><div><h3>Polish until it belongs.</h3><p>Identity, accessibility, motion, performance, responsive behavior, and detail.</p></div><b>↗</b></div>\n<div class=\"approach-step\"><span>04</span><div><h3>Deliver something you control.</h3><p>Written scope, tested handoff, and optional support. No artificial lock-in.</p></div><b>↗</b></div>\n</div></div>\n</section>\n<section class=\"case-section section-frame\" id=\"work\" aria-labelledby=\"case-title\"><div class=\"frame case-layout\"><div class=\"case-copy\"><span class=\"eyebrow\"><span class=\"eyebrow-line\"></span> 04 / LOCAL EXPERIMENT</span><h2 id=\"case-title\">THE LAB MEETS<br><em>MAIN STREET.</em></h2><p>Not every business needs a game engine. Sometimes the most ambitious thing is a remarkable, effortless customer experience.</p><div class=\"case-pills\"><span>LOCAL STOREFRONT</span><span>MOBILE-FIRST</span><span>INDEPENDENT CONCEPT</span></div><a href=\"/preview/tobacco-vapor-time\" class=\"primary-button\">EXPLORE A LOCAL CONCEPT ↗</a><p class=\"disclaimer\">Tobacco Vapor Time is an uncommissioned, independent informational concept—not an endorsed or official business website. No regulated products are offered or sold.</p></div><div class=\"case-visual\" aria-hidden=\"true\"><div class=\"case-ambient\"></div><div class=\"case-display\"><div class=\"case-display-line\"><span>ANEVUM / EXPERIMENTAL STUDY</span><span>NO. 01</span></div><div class=\"case-mark\"><span class=\"mark-orbit one\"></span><span class=\"mark-orbit two\"></span><span class=\"mark-core\"></span></div><div class=\"case-bottom\"><span>ST. CLOUD / 34772</span><span>PLACE · PEOPLE · PRESENCE</span></div></div></div></div></section>\n<section class=\"pricing-section section-frame\" id=\"pricing\" aria-labelledby=\"pricing-title\"><div class=\"frame\"><div class=\"section-header\"><div><span class=\"eyebrow\"><span class=\"eyebrow-line\"></span> 05 / A REALISTIC WAY TO BEGIN</span><h2 id=\"pricing-title\">START WITH A SITE.<br><em>GO BEYOND WHEN READY.</em></h2></div><p class=\"section-intro\">Focused introductory packages for ordinary business websites. Games, 3D worlds, custom apps, integrations, and larger software are quoted separately after scope review.</p></div><div class=\"price-grid\"><article class=\"price-card featured\"><span class=\"price-index\">FOUNDING PILOT / FIRST THREE ELIGIBLE PROJECTS</span><h3>FOUNDING SITE</h3><div class=\"price-amount\">$49 <small>ONE-TIME</small></div><p>One responsive landing page, up to four sections, location/contact links, one revision round.</p><a href=\"#contact\">INQUIRE ↗</a></article><article class=\"price-card\"><span class=\"price-index\">STANDARD / FOCUSED</span><h3>STARTER SITE</h3><div class=\"price-amount\">$99 <small>ONE-TIME</small></div><p>One custom mobile-first page, up to six planned sections, basic on-page SEO, two revision rounds.</p><a href=\"#contact\">INQUIRE ↗</a></article><article class=\"price-card\"><span class=\"price-index\">BUSINESS / UP TO THREE PAGES</span><h3>BUSINESS SITE</h3><div class=\"price-amount\">$199 <small>ONE-TIME</small></div><p>A business-specific visual system, three responsive pages, basic SEO/accessibility review and two revision rounds.</p><a href=\"#contact\">INQUIRE ↗</a></article></div><p class=\"price-fine\">These are limited pilot starting packages, not a price promise for advanced software. Domain registration, hosting, external services, paid integrations, photography, extra work, and optional maintenance cost extra. Written scope and quote always come first.</p></div></section>\n<section class=\"contact-section section-frame\" id=\"contact\" aria-labelledby=\"contact-title\"><div class=\"frame contact-layout\"><div class=\"contact-copy\"><span class=\"eyebrow\"><span class=\"eyebrow-line\"></span> 06 / OPEN A NEW EXPERIMENT</span><h2 id=\"contact-title\">GIVE US THE<br><em>STRANGE IDEA.</em></h2><p>Local storefront or impossible-sounding web application: start by explaining what you want to make real. We'll work out a sensible first build and quote.</p><div class=\"contact-mini\"><span class=\"status-dot\"></span> INDEPENDENT BUILDER · ST. CLOUD, FLORIDA</div><p class=\"contact-email\"><a href=\"mailto:devon@anevum.com?subject=ANEVUM%20Sites%20project\">devon@anevum.com ↗</a></p></div>\n<div class=\"contact-panel\"><div class=\"form-top\"><span>PROJECT INTAKE / 001</span><span><i></i> ACCEPTING INQUIRIES</span></div><form action=\"/api/inquiries\" method=\"post\" id=\"site-inquiry\"><div class=\"form-grid\"><div class=\"form-field\"><label for=\"s-name\">YOUR NAME *</label><input id=\"s-name\" name=\"name\" required minlength=\"2\" maxlength=\"100\" autocomplete=\"name\" placeholder=\"Your name\"></div><div class=\"form-field\"><label for=\"s-company\">BUSINESS OR PROJECT *</label><input id=\"s-company\" name=\"business\" required minlength=\"2\" maxlength=\"120\" autocomplete=\"organization\" placeholder=\"What should we call it?\"></div><div class=\"form-field\"><label for=\"s-email\">EMAIL ADDRESS *</label><input id=\"s-email\" name=\"email\" required type=\"email\" maxlength=\"180\" autocomplete=\"email\" placeholder=\"you@example.com\"></div><div class=\"form-field\"><label for=\"s-phone\">PHONE (OPTIONAL)</label><input id=\"s-phone\" name=\"phone\" type=\"tel\" maxlength=\"45\" autocomplete=\"tel\" placeholder=\"Best callback number\"></div><div class=\"form-field full\"><label for=\"s-website\">CURRENT WEBSITE (OPTIONAL)</label><input id=\"s-website\" name=\"website\" type=\"url\" maxlength=\"240\" placeholder=\"https://yourbusiness.com\"></div><div class=\"form-field full\"><label for=\"s-package\">WHAT ARE YOU ENVISIONING?</label><select id=\"s-package\" name=\"package\"><option value=\"undecided\">Let's discuss an idea</option><option value=\"49\">Founding Site · $49 pilot</option><option value=\"99\">Starter Site · $99</option><option value=\"199\">Business Site · $199</option><option value=\"custom\">Custom app / game / 3D / integration</option></select></div><div class=\"form-field full\"><label for=\"s-goal\">TELL US WHAT YOU WANT TO BUILD *</label><textarea id=\"s-goal\" name=\"goal\" required minlength=\"12\" maxlength=\"1800\" placeholder=\"What's the idea? What should the finished experience actually do?\"></textarea></div></div><div class=\"trap\" aria-hidden=\"true\"><label for=\"s-fax\">Leave blank</label><input id=\"s-fax\" type=\"text\" tabindex=\"-1\" autocomplete=\"off\" name=\"fax_number\"></div><label class=\"consent\"><input type=\"checkbox\" name=\"consent\" value=\"yes\" required><span>I agree to ANEVUM Sites storing my inquiry to respond to this request. I have read the <a href=\"/privacy\">privacy notice</a>.</span></label><button class=\"primary-button submit-button\" type=\"submit\">TRANSMIT PROJECT INQUIRY <span aria-hidden=\"true\">↗</span></button><p class=\"form-note\">No payment is collected here. Inquiries go to our existing private contact desk. Never enter passwords or confidential account details.</p></form></div></div></section>\n</main>\n<footer class=\"footer\"><div class=\"frame footer-top\"><a class=\"brand footer-brand\" href=\"/\"><span class=\"brand-emblem\" aria-hidden=\"true\"><span></span></span><span class=\"brand-word\">ANEVUM<span class=\"brand-slash\"> / </span><span class=\"brand-sites\">SITES</span></span></a><div class=\"footer-tag\">THE INTERNET IS OUR MATERIAL.<br>WHAT SHOULD WE MAKE NEXT?</div><nav aria-label=\"Footer navigation\"><a href=\"#experience\">LAB</a><a href=\"#capabilities\">CAPABILITIES</a><a href=\"/privacy\">PRIVACY</a><a href=\"#contact\">CONTACT</a></nav></div><div class=\"frame footer-bottom\"><span>© 2026 ANEVUM SITES. A CONTINUANCE INSTITUTE EXPERIMENT.</span><span>BUILT WITH INTENT / NOT A TEMPLATE</span></div></footer>\n<script src=\"/assets/sites-v005.js\" defer></script>\n</body></html>";
